[{"order":1,"type":"heading","text":"Client-side State Management Integration with RSC in Next.js"},{"order":2,"type":"paragraph","text":"Integrating client-side state management libraries like React Context, Zustand, or Redux Toolkit into a Next.js application using React Server Components (RSC) requires a clear boundary between server and client execution."},{"order":3,"type":"subheading","text":"The Architecture Challenge"},{"order":4,"type":"paragraph","text":"By default, all components in the Next.js App Router are React Server Components. State management libraries inherently rely on React Context or mutable closures, which only work in Client Components. Therefore, you must initialize and consume stores inside components marked with the 'use client' directive."},{"order":5,"type":"subheading","text":"Approach 1: Zustand with Initial State from RSC"},{"order":6,"type":"paragraph","text":"Zustand is lightweight and allows you to create stores that can be hydrated with data fetched on the server within an RSC."},{"order":7,"type":"code","text":"// lib/store.ts
import { createStore } from 'zustand/vanilla';
import { create } from 'zustand';

interface UserState {
  user: string;
  setUser: (user: string) => void;
}

export const createUserStore = (initialState: { user: string }) => {
  return create<UserState>()((set) => ({
    user: initialState.user,
    setUser: (user) => set({ user }),
  }));
};"},{"order":8,"type":"paragraph","text":"Next, create a provider component to initialize the store safely per-request, avoiding shared state pollution across concurrent requests."},{"order":9,"type":"code","text":"'use client';

import { type ReactNode, createContext, useRef, useContext } from 'react';
import { type StoreApi } from 'zustand';
import { createUserStore } from '@/lib/store';

type UserStoreApi = ReturnType<typeof createUserStore>;

const UserStoreContext = createContext<UserStoreApi | undefined>(undefined);

interface UserStoreProviderProps {
  children: ReactNode;
  initialUser: string;
}

export const UserStoreProvider = ({ children, initialUser }: UserStoreProviderProps) => {
  const storeRef = useRef<UserStoreApi>();
  if (!storeRef.current) {
    storeRef.current = createUserStore({ user: initialUser });
  }

  return (
    <UserStoreContext.Provider value={storeRef.current}>
      {children}
    </UserStoreContext.Provider>
  );
};

export const useUserStore = <T>(selector: (state: ReturnType<UserStoreApi['getState']>) => T): T => {
  const store = useContext(UserStoreContext);
  if (!store) throw new Error('Missing UserStoreProvider');
  return useStore(store, selector);
};"},{"order":10,"type":"subheading","text":"Consuming in Server and Client Boundaries"},{"order":11,"type":"paragraph","text":"In your Server Component, fetch the initial data and pass it down to the Client Provider wrapper."},{"order":12,"type":"code","text":"// app/dashboard/page.tsx
import { UserStoreProvider } from '@/components/UserStoreProvider';
import UserProfile from '@/components/UserProfile';

async function fetchUserData() {
  return { name: 'Jane Doe' };
}

export default async function DashboardPage() {
  const data = await fetchUserData();

  return (
    <UserStoreProvider initialUser={data.name}>
      <main>
        <h1>Dashboard</h1>
        <UserProfile />
      </main>
    </UserStoreProvider>
  );
}"},{"order":13,"type":"subheading","text":"Best Practices for State in RSC"},{"order":14,"type":"bullet_point","text":"Keep server-fetchable data on the server. Do not store database query results inside Redux or Zustand unless client-side mutation is strictly required."},{"order":15,"type":"bullet_point","text":"Use Context and Zustand Providers at the lowest possible layout boundary to maximize the portion of your tree that remains purely server-rendered."},{"order":16,"type":"bullet_point","text":"Avoid global singleton stores on the client when doing SSR in Next.js, as data from user A might leak to user B during concurrent server rendering."}]
